/*
 * pathdef.c for Vim on an Evans Computer Mod computer (normally generated by
 * the Makefile). The runtime files (syntax, filetype plugins, help, defaults.vim)
 * are on the server's read-only program folder, /server-bin/vim.
 */
#include "vim.h"

char_u *default_vim_dir = (char_u *)"/server-bin/vim";
char_u *default_vimruntime_dir = (char_u *)"/server-bin/vim/runtime";
char_u *all_cflags = (char_u *)"wasi-sdk clang --target=wasm32-wasip1 -Os (rust/wasm-programs/vim/build.rs)";
char_u *all_lflags = (char_u *)"cargo build --target wasm32-wasip1 -p vim";
char_u *compiled_user = (char_u *)"ecm";
char_u *compiled_sys = (char_u *)"evanscomputermod";
